 ignoreRange=true;ready=AppUpdates.DownloadTo(Release(),null,CancellationToken.None,dir,8000).GetAwaiter().GetResult();AppUpdates.VerifyInstaller(ready,Release());A(true,"server ignoring Range falls back to verified stream");File.Delete(ready);Reset();
 cutOnce=true;ready=AppUpdates.DownloadTo(Release(),null,CancellationToken.None,dir,20000).GetAwaiter().GetResult();AppUpdates.VerifyInstaller(ready,Release());A(true,"short connection automatically retries and verifies");File.Delete(ready);Reset();
 ready=AppUpdates.DownloadTo(Release(root+"offline.exe",new[]{root+"installer.exe"}),null,CancellationToken.None,dir,8000).GetAwaiter().GetResult();AppUpdates.VerifyInstaller(ready,Release());A(true,"publisher-signed alternate recovers failed installer source");File.Delete(ready);Reset();
