 Thread.Sleep(150);data=new byte[2048];new Random(9).NextBytes(data);ready=AppUpdates.DownloadTo(Release(root+"offline.exe?slot=0",new[]{root+"offline.exe?slot=1",root+"offline.exe?slot=2",root+"installer.exe"}),null,CancellationToken.None,dir,10000).GetAwaiter().GetResult();AppUpdates.VerifyInstaller(ready,Release());A(true,"stream download reaches fourth publisher-signed source");File.Delete(ready);Reset();
